// Tiny spring engine shared by every component.
// Springs, sim-time timers (so slow-mo slows them too), one rAF loop, and token readers.
window.Motion = (() => {
  // theme: shared by every page through localStorage, live-updated by the gallery
  const setTheme = t => { document.documentElement.dataset.theme = t === 'light' ? 'light' : 'dark'; };
  try { setTheme(localStorage.getItem('ms-theme')); } catch { setTheme('dark'); }
  addEventListener('storage', e => { if (e.key === 'ms-theme') setTheme(e.newValue); });

  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const S = (x, k = 400, c = 30) => ({ x, v: 0, t: x, k, c });
  const tune = (s, k, c) => { s.k = k; s.c = reduce ? 2 * Math.sqrt(k) : c; };
  const step = (s, dt) => { const a = -s.k * (s.x - s.t) - s.c * s.v; s.v += a * dt; s.x += s.v * dt; };
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

  // tokens from shared/tokens.css
  const token = (name, fallback = '') =>
    getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback;
  const num = (name, fallback) => parseFloat(token(name, String(fallback)));
  const spring = (name, fallback) => token(name, fallback).split(/\s+/).map(Number);

  let timeScale = 1;
  const timers = [];
  const after = (sec, fn) => { const t = { t: sec, fn }; timers.push(t); return t; };
  const cancel = t => { const i = timers.indexOf(t); if (i > -1) timers.splice(i, 1); };

  // slow motion, synced with a parent page when embedded
  const slowListeners = [];
  function setSlow(v, fromParent = false) {
    timeScale = v ? .25 : 1;
    slowListeners.forEach(f => f(v));
    if (!fromParent && parent !== window) parent.postMessage({ type: 'motion:slow-changed', on: v }, '*');
  }
  addEventListener('message', e => {
    if (e.data && e.data.type === 'motion:slow') setSlow(!!e.data.on, true);
    if (e.data && e.data.type === 'motion:theme') setTheme(e.data.theme);
  });

  const comps = [];
  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 1 / 30) * timeScale; last = now;
    for (let i = timers.length - 1; i >= 0; i--) {
      if ((timers[i].t -= dt) <= 0) timers.splice(i, 1)[0].fn();
    }
    const sub = 4;
    for (let k = 0; k < sub; k++) comps.forEach(c => c.frame(dt / sub));
    comps.forEach(c => c.render());
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return {
    S, tune, step, clamp, token, num, spring, after, cancel,
    register: c => comps.push(c),
    get timeScale() { return timeScale; },
    get slow() { return timeScale !== 1; },
    setSlow, onSlow: f => slowListeners.push(f),
    svg: (p, sw = 1.8) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${p}</svg>`,
  };
})();

/* Word Roll: the last word of a line rolls to the next one, letter by letter.
   The lead and the slot share one line height, so centring them is the same as
   sitting them on one baseline. The slot clips top and bottom only. */
.roll{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  display:flex;align-items:center;gap:.26em;white-space:nowrap;cursor:pointer;outline:none;
  font-family:var(--font-inter,Inter),Inter,"Helvetica Neue",Arial,sans-serif;
  font-size:min(44px,calc(100vw * .084));font-weight:var(--fw-bold);letter-spacing:-.035em;line-height:1.25;
}
.lead{color:var(--muted)}
.slot{position:relative;display:block;height:1.25em;color:var(--text);clip-path:inset(0 -.5em)}
.word{position:absolute;left:0;top:0;display:flex}
.ch{display:inline-block;white-space:pre;will-change:transform,opacity}
.roll:focus-visible .slot{color:var(--text)}

// Word Roll
// The last word rolls up and out letter by letter while the next one rolls in
// from below, and the space it sits in stretches to the new width on a spring.
// Turns by itself; click (or Enter) to turn now.
(() => {
  const { S, step, clamp, after, cancel } = Motion;
  const $ = id => document.getElementById(id);
  const roll = $('roll'), slot = $('slot');
  const WORDS = ['designers', 'founders', 'makers', 'teams'];
  const width = S(0, 320, 30);
  let live = [], i = 0, timer = null;

  function make(word) {
    const el = document.createElement('span');
    el.className = 'word';
    const letters = [...word].map(ch => {
      const l = document.createElement('span');
      l.className = 'ch';
      l.textContent = ch;
      el.appendChild(l);
      return { el: l, s: S(1, 420, 26) };   // 1 = below the slot, 0 = in place, -1 = above
    });
    slot.appendChild(el);
    return { el, letters, out: false };
  }

  function show(word, first) {
    live.forEach(w => {
      if (w.out) return;
      w.out = true;
      w.letters.forEach((l, k) => after(k * .022, () => { l.s.t = -1; }));
      after(1, () => { w.el.remove(); live = live.filter(x => x !== w); });
    });
    const w = make(word);
    w.letters.forEach((l, k) => {
      if (first) l.s.x = l.s.t = 0;
      else after(.06 + k * .028, () => { l.s.t = 0; });
    });
    live.push(w);
    width.t = w.el.offsetWidth;
    if (first) width.x = width.t;
    roll.setAttribute('aria-label', `Built for ${word}`);
  }

  function schedule() { if (timer) cancel(timer); timer = after(2.4, next); }
  function next() { i = (i + 1) % WORDS.length; show(WORDS[i]); schedule(); }

  roll.addEventListener('click', next);
  roll.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); next(); } });
  show(WORDS[0], true);
  schedule();
  // The first width was measured in the fallback font.
  if (document.fonts) document.fonts.ready.then(() => { const w = live[live.length - 1]; width.t = w.el.offsetWidth; });

  Motion.register({
    frame(dt) {
      step(width, dt);
      live.forEach(w => w.letters.forEach(l => step(l.s, dt)));
    },
    render() {
      slot.style.width = width.x + 'px';
      live.forEach(w => w.letters.forEach(l => {
        const y = l.s.x;
        l.el.style.transform = `translateY(${y * 105}%)`;
        l.el.style.opacity = clamp(1 - Math.abs(y) * .9, 0, 1);
      }));
    },
  });
})();

